import React, { useEffect, useState } from 'react';
import axios from 'axios';

function HomePage() {
  const [studio, setStudio] = useState(null);
  const [projects, setProjects] = useState([]);
  const [awards, setAwards] = useState([]);

  useEffect(() => {
    axios.get('http://localhost:5000/api/studio').then(res => setStudio(res.data));
    axios.get('http://localhost:5000/api/projects').then(res => setProjects(res.data));
    axios.get('http://localhost:5000/api/awards').then(res => setAwards(res.data));
  }, []);

  return (
    <div style={{ padding: 32 }}>
      <h1>{studio ? studio.name : 'Loading Studio...'}</h1>
      <p>{studio && studio.description}</p>
      <h2>Projects</h2>
      <ul>
        {projects.map(project => (
          <li key={project._id}>{project.title} - {project.client}</li>
        ))}
      </ul>
      <h2>Awards</h2>
      <ul>
        {awards.map(award => (
          <li key={award._id}>{award.type}: {award.title} ({award.date})</li>
        ))}
      </ul>
    </div>
  );
}

export default HomePage;
